func:
if (typeof msg.payload !== 'object' ||
    typeof msg.payload.hmi !== 'object' ||
    typeof msg.payload.project !== 'string'
) {
    return;
}

msg.filename = '/data/projects/' + msg.payload.project + '/package.json'

msg.payload.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': ''
}

global.set('describe', msg.payload, 'memoryOnly');

return msg;

// DKNR MQTT topic
const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
if (!enabled || topic === '') {

    return;
}

const ha_topic = global.get('mqtt.homeassistant', 'default') || '';

const controls = global.get('controls', 'memoryOnly') || {};
const describe = global.get('describe', 'memoryOnly') || {};
const source = 'rfxcom';

//...
for (const k in controls) {
    // topic as uid must be source _ id _ entry
    let dknrMsg = {
        'topic': [topic, 'discovery', source, controls[k]['device'], controls[k]['entity']].join('/'),
        'payload': {
            'name': controls[k]['name'],
            'group': controls[k]['group'],
            'type': controls[k]['type'],
            'unit': controls[k]['unit'],
            'value': controls[k]['value'],
            'options': {}
        },
        'qos': 0,
        'retain': true
    };

    node.send(dknrMsg);

    // ha
    msg.topic = ha_topic + '/' + controls[k]['ha_type'] + '/rfxcom/' + controls[k]['device'] + '_' + controls[k]['entity'] + '/config';

    if (controls[k]['ha_type'] === 'sensor') {
        msg.payload = {
            'unique_id': ['dknr', source, controls[k]['device'], controls[k]['entity']].join('_'),
            'name': controls[k]['name'],
            'state_topic': [topic, 'get', source, controls[k]['device'], controls[k]['entity']].join('/'),
            'state_class': controls[k]['ha_state'],
            'device_class': controls[k]['ha_device'],
            'unit_of_measurement': controls[k]['unit'],
            'device': {
                'identifiers': [
                    controls[k]['device']
                ],
                'manufacturer': 'RFXCom',
                'model': 'rfxcom ' + controls[k]['device'],
                'name': 'RFXCom ' + controls[k]['device']
            }
        };

        node.send(msg);
    }
    else if (controls[k]['ha_type'] === 'switch') {
        msg.payload = {
            'unique_id': ['dknr', source, controls[k]['device'], controls[k]['entity']].join('_'),
            'name': controls[k]['name'],
            'payload_off': 0,
            'payload_on': 1,
            'state_off': 0,
            'state_on': 1,
            'command_topic': [topic, 'set', source, controls[k]['device'], controls[k]['entity']].join('/'),
            'state_topic': [topic, 'get', source, controls[k]['device'], controls[k]['entity']].join('/'),
            'device': {
                'identifiers': [
                    controls[k]['device']
                ],
                'manufacturer': 'RFXCom',
                'model': 'rfxcom ' + controls[k]['device'],
                'name': 'RFXCom ' + controls[k]['device']
            }
        };

        node.send(msg);
    }
}

return;

const mqtt = global.get('mqtt', 'default') || { };
if (!mqtt.enabled || typeof mqtt.source !== 'string' || mqtt.source === '') {
    node.status({ 'fill': 'red', 'text': 'settings nok' });

    return;
}

msg.topic = [mqtt.source, 'devices', '#'].join('/');
msg.payload = '';
msg.broker = {};
msg.broker.broker = mqtt.host;
msg.broker.port = mqtt.port;
msg.broker.username = mqtt.username;
msg.broker.password = mqtt.password;

msg.broker.force = true;
msg.action = 'connect';

node.send([msg]);

delete msg.broker;

await new Promise(resolve => setTimeout(resolve, 1000));

msg.topic = [mqtt.source, 'devices', '#'].join('/');
msg.payload = '';
msg.action = 'subscribe';
msg.qos = 1;

node.send([msg]);

node.status({fill:"green",shape:"ring",text:"settings ok"});

return;

// Remove this type
const disabled = global.get('disabled', 'default');
for (let i = 0; i< disabled.length; i++) {
    if (Object.hasOwn(msg.payload, disabled[i][0]) && msg.payload[disabled[i][0]] === disabled[i][1]) {

        return;
    }
}

if (typeof global.get('controls', 'memoryOnly') !== 'object') {
    global.set('controls', { }, 'memoryOnly');
    await new Promise(resolve => setTimeout(resolve, 10));
}

const topic = global.get('mqtt.topic');
const source = 'rfxcom';

const path = msg.topic.split('/');
if (path.length < 2) {

    return;
}

let device = path.pop();
if (device === 'devices') {

    return;
}
let sub = path.pop();
if (sub !== 'devices') {
    device = sub;//(sub + '-' + device).slice(2);
}
device = device.slice(2);
let value = '';

let controls = global.get('controls', 'memoryOnly');

for (let entity in msg.payload) {
    let exists = true;
    let control = {
        'device': device,
        'entity': entity,
        'name': '',
        'group': 'sensor',
        'type': 'number',
        'unit': '',
        'value': 0,
        'options': {},
        'ha_type': 'sensor',
        'ha_state': 'measurement',
        'ha_device': 'none'
    };

    switch (entity) {
        case 'batteryLevel':
            value = msg.payload.batteryLevel * 10;

            control.name = 'Batterie';
            control.unit = '%';
            control.ha_device = 'battery';
            break;
        case 'rssi':
            value = msg.payload.rssi;

            control.name = 'Signal';
            control.unit = 'dBm';
            control.ha_device = 'signal_strength';
            break;
        case 'command':
            value = msg.payload[entity] == 'On' ? 1 : 0;
            entity = 'command' + msg.payload.unitCode;

            control.entity = entity;
            control.name = 'Bouton ' + msg.payload.unitCode;
            control.ha_type = 'switch';
            break;
        case 'humidity':
            value = msg.payload.humidity;

            control.name = 'Humidité';
            control.unit = '%';
            control.ha_device = 'humidity';
            break;
        case 'temperature':
            value = msg.payload.temperature;

            control.name = 'Température';
            control.unit = '°C';
            control.ha_device = 'temperature';
            break;
        default:
            exists = false;
    }

    if (exists) {
        let uid = device + '_' + entity;

        controls[uid] = { ...control };

        if (flow.get('last["' + uid + '"]', 'memoryOnly') !== value) {
            flow.set('last["' + uid + '"]', value, 'memoryOnly');

            let dknr = {
                'topic': [topic, 'get', source, device, entity].join('/'),
                'payload': value,
                'qos': 0,
                'retain': false
            };

            node.send([dknr]);
        }

        await new Promise(resolve => setTimeout(resolve, 10));
    }
}


return;

const disabled = global.get('disabled', 'default') || { };

msg.payload = [];

for (let i = 0; i < disabled.length; i++) {
    msg.payload.push({
        'index': i,
        'key': disabled[i][0],
        'value': disabled[i][1],
        'delete': 'Supprimer'
    });
}

return msg;

if (msg.payload.key !== '' && msg.payload.value !== '') {
    let disabled = global.get('disabled', 'default');
    disabled.push([msg.payload.key, msg.payload.value]);
    msg.payload = '';

    await new Promise(resolve => setTimeout(resolve, 10));

    return msg;
}

return;

if (msg.action === 'button_click' && msg.column === 'delete') {
    let disabled = global.get('disabled', 'default');
    disabled.splice(msg.payload.index, 1);
    msg.payload = '';

    return msg;
}

return;

const controls = global.get('controls', 'memoryOnly') || { };

msg.payload = [];

for (const k in controls) {
    msg.payload.push(controls[k]);
}

return msg;
